export const inventoryCycleDefinitions={
 inventoryCycle:{title:'Follow repeated inventory batches through a fixed 365-day cash window',fields:[
  ['cash','Business cash available at day zero (CAD)',10000,0,100000,1000],
  ['batchCost','Inventory cost per complete batch (CAD)',5000,100,25000,100],
  ['batchSale','Revenue per complete batch when sold (CAD)',8000,0,50000,100],
  ['stockBatches','Number of identical batches ordered',6,1,6,1],
  ['orderSpacingDays','Days between inventory orders',30,7,30,1],
  ['stockDays','Days from each order to its full sale',30,0,60,1],
  ['buyerDelayDays','Days from each sale to full customer payment',30,0,60,1],
  ['supplierDelayDays','Days from each order to full supplier payment',15,0,60,1],
  ['dailyOverhead','Cash operating overhead per day, days 1–365 (CAD)',20,0,100,5],
  ['viewDay','Day of the inventory/receivable/payable snapshot',40,0,365,1]
 ]}
};
export function inventoryCashCycle(input) {
 const batches=Array.from({length:input.stockBatches},(_,i)=>{
  const order=i*input.orderSpacingDays,sale=order+input.stockDays;return {order,sale,collect:sale+input.buyerDelayDays,pay:order+input.supplierDelayDays};
 });
 let netCash=0,profit=0,minimum=0;const rows=[];
 for(let day=0;day<=365;day++) {
  const overhead=day===0?0:input.dailyOverhead,sales=batches.filter(b=>b.sale===day).length,collections=batches.filter(b=>b.collect===day).length,payments=batches.filter(b=>b.pay===day).length;
  profit+=sales*(input.batchSale-input.batchCost)-overhead;netCash+=collections*input.batchSale-payments*input.batchCost-overhead;minimum=Math.min(minimum,netCash);
  const inventory=batches.filter(b=>b.order<=day&&day<b.sale).length*input.batchCost,receivables=batches.filter(b=>b.sale<=day&&day<b.collect).length*input.batchSale,payables=batches.filter(b=>b.order<=day&&day<b.pay).length*input.batchCost;
  rows.push({x:day,netCash,cash:input.cash+netCash,profit,inventory,receivables,payables});
 }
 const requiredStartingCash=Math.max(0,-minimum);
 return {batches,rows,requiredStartingCash,extraCash:Math.max(0,requiredStartingCash-input.cash),profit,endingCash:input.cash+netCash,interval:input.stockDays+input.buyerDelayDays-input.supplierDelayDays,snapshot:rows[input.viewDay]};
}
export function inventoryCycleResult(kind,input) {
 if(kind!=='inventoryCycle')throw Error('Unknown inventory-cycle topic.');
 const p=inventoryCashCycle(input),s=p.snapshot;
 return {metrics:[['Minimum starting cash for a non-negative day-end ledger',p.requiredStartingCash,'money'],['Extra initial cash above the entered business balance',p.extraCash,'money'],['Simplified 365-day operating result before owner withdrawals',p.profit,'money']],note:'Original deterministic batch-trading illustration over days 0–365. Identical batches are ordered at the chosen spacing, beginning on day zero; each is sold in full after the entered stock days, collected in full after the buyer delay, and paid to the supplier after the supplier delay measured from the order. Supplier credit and customer terms are assumptions, not accepted offers or permitted late payments. Every supported batch is sold, collected and paid within day 365. Inventory is recorded at batch cost; customer invoices at the entered sale price. Simplified profit recognises batch revenue less batch inventory cost on sale day, and the cash overhead on each day 1–365. Overhead continues through the full fixed year even after the final batch settles. Net trading cash records actual collections less supplier payments and the same overhead; starting cash is added only to the separate cash-balance view. Daily netting omits intraday funding needs. Negative cash balances are unfunded positions, not automatic credit. No tax, interest, fees, discounts, wages beyond entered costs, owner withdrawal, unsold stock, bad debt or depreciation is modeled. The displayed per-batch interval uses authored event lags, not average-day ratios estimated from actual financial statements.',charts:[
  {id:'inventory-cycle-days-bridge',type:'waterfall',title:'The authored payment-to-collection interval for each batch',unit:'integer',unitLabel:'Days per hypothetical batch · a negative total means collection precedes supplier payment',rows:[{label:'Order to full sale',value:input.stockDays},{label:'Sale to customer payment',value:input.buyerDelayDays},{label:'Supplier payment delay',value:-input.supplierDelayDays}],totalLabel:'Supplier payment to collection',evidence:'Hypothetical fixed event lags',note:'Order-to-sale days plus sale-to-collection days less order-to-supplier-payment days gives the interval between the supplier outflow and customer receipt for each identical batch. It describes timing, not the amount of cash needed. A negative interval does not remove the supplier liability or make incoming customer cash available for unrestricted household spending.'},
  {id:'inventory-cycle-profit-cash',type:'line',title:'Simplified profit and net trading cash can diverge before settlement',unit:'money',xLabel:'Days in the fixed 365-day window',series:[{name:'Cumulative simplified operating result',rows:p.rows.map(r=>({x:r.x,value:r.profit}))},{name:'Net trading cash, excluding starting cash',rows:p.rows.map(r=>({x:r.x,value:r.netCash})),dash:true}],evidence:'Hypothetical accrual and receipt timing',note:'Profit recognises the batch margin when a full batch is sold. Net trading cash waits for customer receipts and supplier payments. Both deduct the same daily cash overhead. Starting cash is excluded from both series so it does not create a permanent offset between them. Once all stock, receivables and payables are cleared, the two measures reconcile; this is not a forecast of real business profit.'},
  {id:'inventory-cycle-cash-balance',type:'line',title:'Business cash after the entered starting balance',unit:'money',xLabel:'Days in the fixed 365-day window',series:[{name:'Day-end business cash ledger',rows:p.rows.map(r=>({x:r.x,value:r.cash}))}],evidence:'Hypothetical day-end funding ledger',note:'This line adds the entered starting cash to net trading cash. Its largest deficit identifies the additional initial funding metric. A positive final balance does not establish that every earlier payment was funded. The calculation assumes same-day receipts can offset same-day outflows and does not test earlier intraday deadlines, access restrictions or a financing facility.'},
  {id:'inventory-cycle-terms-matrix',type:'heatmap',title:'Extra initial cash under different customer and supplier payment lags',unit:'money',columns:[0,15,30,60].map(v=>v+' d'),rows:[0,15,30,60].map(buyerDelayDays=>({label:'Buyer '+buyerDelayDays+' d',values:[0,15,30,60].map(supplierDelayDays=>inventoryCashCycle({...input,buyerDelayDays,supplierDelayDays}).extraCash)})),evidence:'Hypothetical payment-term sensitivity',note:'Rows replace the customer delay after sale; columns replace supplier payment days after ordering. Each cell is extra starting cash above the entered balance needed over the same 365-day window. Batch volumes, margins, stock days, overhead and starting cash remain selected assumptions. The grid assumes each alternative term is agreed and all payments occur as modeled; it does not recommend paying suppliers late or assign a probability to customer behaviour.'},
  {id:'inventory-cycle-noncash-bridge',type:'waterfall',title:'Reconcile profit less net trading cash at day '+input.viewDay,unit:'money',rows:[{label:'Unsold inventory at batch cost',value:s.inventory},{label:'Unpaid customer invoices',value:s.receivables},{label:'Unpaid inventory suppliers',value:-s.payables}],totalLabel:'Result less net trading cash',evidence:'Hypothetical non-cash trade balances',note:'At the selected day-end, inventory plus unpaid customer invoices less unpaid supplier amounts equals the difference between the simplified operating result and net trading cash. This is a ledger identity for these modeled trades, not a fair-value assessment or the business’s complete working-capital measure. It excludes the starting cash balance and does not treat either stock or an invoice as cash already collected.'}
 ]};
}
